DO $seed$
DECLARE
  problem_data JSONB;
  problem_id UUID;
  topic_id UUID;
  subtopic_id UUID;
  tag_slug TEXT;
  tag_id UUID;
  example_data JSONB;
  example_index INTEGER;
  private_test_count INTEGER := 0;
  cpp_starter TEXT := E'#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // Read the input format and print the required result.\n    return 0;\n}\n';
  python_starter TEXT := E'import sys\n\ndef solve():\n    data = sys.stdin.read().split()\n    # Read the input format and print the required result.\n\nif __name__ == "__main__":\n    solve()\n';
  seeded_easy INTEGER := 0;
  seeded_medium INTEGER := 0;
  seeded_hard INTEGER := 0;
  published_easy INTEGER;
  published_medium INTEGER;
  published_hard INTEGER;
  published_total INTEGER;
BEGIN
  FOR problem_data IN
    SELECT value FROM jsonb_array_elements($problems$
[
  {"slug":"extra-distinct-value-count","title":"Distinct Value Count","difficulty":"easy","topic":"arrays","subtopic":"array-traversal","description":"Given an integer sequence, count the number of different values it contains.","input_format":"An integer n followed by n integers.","output_format":"Print the number of distinct values.","constraints":["0 <= n <= 200000","-10^9 <= value <= 10^9"],"examples":[{"input":"5\n4 2 4 7 2","output":"3"},{"input":"4\n9 9 9 9","output":"1"}],"hints":[{"text":"A set stores each value at most once."}],"tags":["array-scan","hash-map"],"private_input":"0","private_output":"0"},
  {"slug":"extra-second-distinct-maximum","title":"Second Distinct Maximum","difficulty":"easy","topic":"arrays","subtopic":"array-fundamentals","description":"Find the second-largest distinct value in a sequence. Print NONE if fewer than two distinct values exist.","input_format":"An integer n followed by n integers.","output_format":"Print the second-largest distinct value or NONE.","constraints":["1 <= n <= 200000","-10^9 <= value <= 10^9"],"examples":[{"input":"6\n5 1 5 3 2 3","output":"3"},{"input":"4\n8 8 8 8","output":"NONE"}],"hints":[{"text":"Track the largest and second-largest distinct values during one scan."}],"tags":["array-scan"],"private_input":"5\n-4 -1 -9 -1 -3","private_output":"-3"},
  {"slug":"extra-right-rotate-sequence","title":"Rotate a Sequence Right","difficulty":"easy","topic":"arrays","subtopic":"array-fundamentals","description":"Rotate an integer sequence to the right by k positions. Rotations may exceed the sequence length.","input_format":"Integers n and k, followed by n integers.","output_format":"Print the rotated sequence on one line.","constraints":["1 <= n <= 200000","0 <= k <= 10^18","-10^9 <= value <= 10^9"],"examples":[{"input":"5 2\n1 2 3 4 5","output":"4 5 1 2 3"},{"input":"4 8\n7 6 5 4","output":"7 6 5 4"}],"hints":[{"text":"Reduce k modulo n before moving any values."}],"tags":["array-scan","two-pointers"],"private_input":"3 1\n-1 0 2","private_output":"2 -1 0"},
  {"slug":"extra-missing-permutation-value","title":"Missing Permutation Value","difficulty":"easy","topic":"arrays","subtopic":"array-traversal","description":"An array contains n distinct values chosen from 0 through n. Find the one missing value.","input_format":"An integer n followed by n distinct integers.","output_format":"Print the missing value.","constraints":["0 <= n <= 200000","0 <= value <= n"],"examples":[{"input":"3\n0 1 3","output":"2"},{"input":"5\n1 2 3 4 5","output":"0"}],"hints":[{"text":"Compare the expected sum from 0 through n with the input sum."}],"tags":["array-scan","hash-map"],"private_input":"1\n0","private_output":"1"},
  {"slug":"extra-reverse-word-order","title":"Reverse Word Order","difficulty":"easy","topic":"strings","subtopic":"string-traversal","description":"Reverse the order of the words in a line while keeping each word unchanged. Words are separated by single spaces.","input_format":"One non-empty line containing lowercase words separated by spaces.","output_format":"Print the words in reverse order separated by single spaces.","constraints":["1 <= line length <= 200000","Words contain lowercase English letters."],"examples":[{"input":"learn data structures","output":"structures data learn"},{"input":"solo","output":"solo"}],"hints":[{"text":"Split the line into words, then visit the words from right to left."}],"tags":["strings"],"private_input":"small steps every day","private_output":"day every steps small"},
  {"slug":"extra-first-unique-character","title":"First Unique Character","difficulty":"easy","topic":"strings","subtopic":"character-frequency","description":"Find the zero-based index of the first character that occurs exactly once. Print -1 if every character repeats.","input_format":"One non-empty lowercase string.","output_format":"Print the first unique character index or -1.","constraints":["1 <= string length <= 200000","The string contains lowercase English letters."],"examples":[{"input":"swiss","output":"1"},{"input":"aabb","output":"-1"}],"hints":[{"text":"Count each character, then scan the string again from the beginning."}],"tags":["strings","hash-map"],"private_input":"leetcode","private_output":"0"},
  {"slug":"extra-run-length-encoding","title":"Run-Length Encoding","difficulty":"easy","topic":"strings","subtopic":"string-traversal","description":"Encode each maximal run of equal adjacent lowercase letters as the letter followed by the run length.","input_format":"A non-empty lowercase string.","output_format":"Print the encoded string, such as a3b1 for aaab.","constraints":["1 <= string length <= 200000","The string contains lowercase English letters."],"examples":[{"input":"aaabbc","output":"a3b2c1"},{"input":"z","output":"z1"}],"hints":[{"text":"Start a new run whenever the current character differs from the previous one."}],"tags":["strings"],"private_input":"aabbbbb","private_output":"a2b5"},
  {"slug":"extra-string-palindrome-check","title":"String Palindrome Check","difficulty":"easy","topic":"strings","subtopic":"palindromes","description":"Determine whether a lowercase string reads identically from left to right and right to left.","input_format":"One non-empty lowercase string.","output_format":"Print YES if it is a palindrome and NO otherwise.","constraints":["1 <= string length <= 200000","The string contains lowercase English letters."],"examples":[{"input":"level","output":"YES"},{"input":"senitor","output":"NO"}],"hints":[{"text":"Compare matching positions from the two ends."}],"tags":["strings","two-pointers"],"private_input":"a","private_output":"YES"},
  {"slug":"extra-distinct-array-intersection","title":"Distinct Array Intersection","difficulty":"easy","topic":"hashing","subtopic":"hash-maps-and-sets","description":"Print the distinct values present in both integer arrays in increasing order.","input_format":"Integers n and m, followed by n integers and then m integers.","output_format":"Print the common distinct values in increasing order, or NONE if there are none.","constraints":["0 <= n,m <= 100000","-10^9 <= value <= 10^9"],"examples":[{"input":"5 4\n1 2 2 3 5\n2 2 4 5","output":"2 5"},{"input":"2 2\n1 3\n2 4","output":"NONE"}],"hints":[{"text":"Store one array in a set and collect each shared value once."}],"tags":["hash-map","sorting"],"private_input":"3 3\n-1 0 2\n2 -1 2","private_output":"-1 2"},
  {"slug":"extra-frequency-query","title":"Frequency Queries","difficulty":"easy","topic":"hashing","subtopic":"frequency-counting","description":"For each query value, report how many times it occurs in the given sequence.","input_format":"Integers n and q, then n sequence values and q query values.","output_format":"Print one frequency per query, each on its own line.","constraints":["1 <= n,q <= 200000","-10^9 <= values and queries <= 10^9"],"examples":[{"input":"5 3\n2 1 2 3 2\n2 4 1","output":"3\n0\n1"},{"input":"3 2\n7 7 7\n7 8","output":"3\n0"}],"hints":[{"text":"Build a frequency map in one pass, then answer each query with one lookup."}],"tags":["hash-map"],"private_input":"4 2\n0 -1 0 2\n0 -1","private_output":"2\n1"},
  {"slug":"extra-most-frequent-value","title":"Most Frequent Value","difficulty":"easy","topic":"hashing","subtopic":"frequency-counting","description":"Print the value with the highest frequency. If multiple values tie, print the smallest tied value.","input_format":"An integer n followed by n integers.","output_format":"Print the most frequent value.","constraints":["1 <= n <= 200000","-10^9 <= value <= 10^9"],"examples":[{"input":"7\n4 2 4 2 4 2 8","output":"2"},{"input":"5\n9 1 7 3 5","output":"1"}],"hints":[{"text":"Count each value, then compare frequency first and numeric value second."}],"tags":["hash-map"],"private_input":"6\n-2 -2 0 0 1 1","private_output":"-2"},
  {"slug":"extra-pair-sum-sorted","title":"Pair Sum in a Sorted Sequence","difficulty":"easy","topic":"two-pointers-and-sliding-window","subtopic":"opposite-direction-pointers","description":"Determine whether two distinct positions in a sorted sequence contain values whose sum is the target.","input_format":"Integers n and target, followed by n sorted integers.","output_format":"Print YES if such a pair exists, otherwise NO.","constraints":["0 <= n <= 200000","-10^9 <= value,target <= 10^9","Values are sorted in nondecreasing order."],"examples":[{"input":"6 10\n1 2 4 6 8 9","output":"YES"},{"input":"4 3\n1 1 1 1","output":"NO"}],"hints":[{"text":"Compare the sum at the two ends and move the pointer that can improve it."}],"tags":["two-pointers"],"private_input":"3 0\n-4 0 4","private_output":"YES"},
  {"slug":"extra-sorted-squares","title":"Sorted Squares","difficulty":"easy","topic":"two-pointers-and-sliding-window","subtopic":"opposite-direction-pointers","description":"Given a sorted integer sequence, print the squares in nondecreasing order.","input_format":"An integer n followed by n sorted integers.","output_format":"Print n squared values in nondecreasing order.","constraints":["0 <= n <= 200000","-10^9 <= value <= 10^9","Values are sorted in nondecreasing order."],"examples":[{"input":"5\n-7 -2 0 3 8","output":"0 4 9 49 64"},{"input":"4\n-3 -1 1 2","output":"1 1 4 9"}],"hints":[{"text":"The largest square must come from one of the two ends."}],"tags":["two-pointers","sorting"],"private_input":"3\n-2 0 1","private_output":"0 1 4"},
  {"slug":"extra-unique-sorted-values","title":"Unique Sorted Values","difficulty":"easy","topic":"two-pointers-and-sliding-window","subtopic":"same-direction-pointers","description":"Remove repeated values from a sorted sequence and print each distinct value once in sorted order.","input_format":"An integer n followed by n sorted integers.","output_format":"Print the distinct values on one line, or NONE for an empty sequence.","constraints":["0 <= n <= 200000","-10^9 <= value <= 10^9","Values are sorted in nondecreasing order."],"examples":[{"input":"8\n1 1 2 2 2 4 7 7","output":"1 2 4 7"},{"input":"0","output":"NONE"}],"hints":[{"text":"Append a value only when it differs from the last value you kept."}],"tags":["two-pointers"],"private_input":"5\n-3 -3 0 1 1","private_output":"-3 0 1"},
  {"slug":"extra-count-sorted-target","title":"Count a Target in Sorted Data","difficulty":"easy","topic":"searching-and-sorting","subtopic":"binary-search-fundamentals","description":"Count the occurrences of a target value in a sorted integer sequence.","input_format":"Integers n and target, followed by n sorted integers.","output_format":"Print the number of occurrences of target.","constraints":["0 <= n <= 200000","-10^9 <= value,target <= 10^9"],"examples":[{"input":"7 4\n1 2 4 4 4 8 9","output":"3"},{"input":"4 3\n1 2 5 7","output":"0"}],"hints":[{"text":"Find the first and one-past-last positions of the target with binary search."}],"tags":["binary-search"],"private_input":"5 -1\n-1 -1 0 2 9","private_output":"2"},
  {"slug":"extra-insertion-position","title":"Sorted Insertion Position","difficulty":"easy","topic":"searching-and-sorting","subtopic":"binary-search-fundamentals","description":"Find the index where a target should be inserted into a sorted sequence to keep it sorted. Existing equal values come after the returned position.","input_format":"Integers n and target, followed by n sorted integers.","output_format":"Print the first index whose value is at least target, or n.","constraints":["0 <= n <= 200000","-10^9 <= value,target <= 10^9"],"examples":[{"input":"5 5\n1 3 5 6 9","output":"2"},{"input":"4 10\n1 2 4 8","output":"4"}],"hints":[{"text":"Maintain a half-open search interval and find the lower bound."}],"tags":["binary-search"],"private_input":"3 -5\n-4 0 2","private_output":"0"},
  {"slug":"extra-remove-list-value","title":"Remove a Value from a List","difficulty":"easy","topic":"linked-lists","subtopic":"traversal-and-search","description":"Remove every occurrence of a target from a sequence representing a linked list and print the remaining values.","input_format":"Integers n and target, followed by n list values.","output_format":"Print remaining values in original order, or NONE if the list becomes empty.","constraints":["0 <= n <= 200000","-10^9 <= value,target <= 10^9"],"examples":[{"input":"6 3\n3 1 3 2 3 4","output":"1 2 4"},{"input":"3 7\n7 7 7","output":"NONE"}],"hints":[{"text":"Build a new sequence by keeping only values different from the target."}],"tags":["linked-list"],"private_input":"4 0\n-1 0 1 0","private_output":"-1 1"},
  {"slug":"extra-kth-from-list-end","title":"K-th Value from the End","difficulty":"easy","topic":"linked-lists","subtopic":"fast-and-slow-pointers","description":"For a non-empty list, print the k-th value from its end, where k equals 1 for the last value.","input_format":"Integers n and k, followed by n list values.","output_format":"Print the k-th value from the end.","constraints":["1 <= k <= n <= 200000","-10^9 <= value <= 10^9"],"examples":[{"input":"5 2\n10 20 30 40 50","output":"40"},{"input":"1 1\n-7","output":"-7"}],"hints":[{"text":"The zero-based index from the start is n minus k."}],"tags":["linked-list","two-pointers"],"private_input":"4 4\n8 6 4 2","private_output":"8"},
  {"slug":"extra-next-greater-value","title":"Next Greater Value","difficulty":"easy","topic":"stacks-and-queues","subtopic":"monotonic-stacks","description":"For each sequence value, find the first greater value to its right. Print -1 when no greater value exists.","input_format":"An integer n followed by n integers.","output_format":"Print one next-greater value for each input value.","constraints":["0 <= n <= 200000","-10^9 <= value <= 10^9"],"examples":[{"input":"5\n2 1 4 3 5","output":"4 4 5 5 -1"},{"input":"4\n4 3 2 1","output":"-1 -1 -1 -1"}],"hints":[{"text":"Keep unresolved indices on a stack and resolve them when a larger value arrives."}],"tags":["stack"],"private_input":"3\n1 2 3","private_output":"2 3 -1"},
  {"slug":"extra-queue-ticket-time","title":"Queue Ticket Time","difficulty":"easy","topic":"stacks-and-queues","subtopic":"queue-and-deque-fundamentals","description":"People stand in a queue. Serving one person takes one minute. Find the minute when the person initially at position k finishes, counting the first minute as minute 1.","input_format":"Integers n and k, followed by n positive ticket counts.","output_format":"Print the number of minutes until person k finishes.","constraints":["1 <= n <= 200000","0 <= k < n","1 <= tickets[i] <= 10^9"],"examples":[{"input":"4 1\n2 3 2 1","output":"8"},{"input":"3 0\n1 5 2","output":"1"}],"hints":[{"text":"People before k can be served at most tickets[k] times; people after k at most tickets[k]-1."}],"tags":["queue"],"private_input":"3 2\n3 1 2","private_output":"5"},
  {"slug":"extra-recursive-digit-sum","title":"Recursive Digit Sum","difficulty":"easy","topic":"recursion-and-backtracking","subtopic":"call-stack-and-base-cases","description":"Compute the sum of the decimal digits of a nonnegative integer using a recursive definition.","input_format":"One nonnegative integer n.","output_format":"Print the sum of its digits.","constraints":["0 <= n <= 10^18"],"examples":[{"input":"5831","output":"17"},{"input":"0","output":"0"}],"hints":[{"text":"Separate the last digit with a remainder operation and recurse on the remaining prefix."}],"tags":["backtracking"],"private_input":"999999","private_output":"54"},
  {"slug":"extra-tree-height-level-order","title":"Tree Height from Level Order","difficulty":"easy","topic":"trees-and-binary-search-trees","subtopic":"tree-representation","description":"A binary tree is encoded in level order using # for a missing node. Find its height in edges; an empty tree has height 0.","input_format":"Space-separated level-order node values, with # for missing nodes.","output_format":"Print the tree height in edges.","constraints":["1 <= token count <= 200000","Node values are distinct integers."],"examples":[{"input":"8 4 12 2 6 # 14","output":"2"},{"input":"5","output":"0"}],"hints":[{"text":"Track each node depth while traversing the level-order representation."}],"tags":["tree-traversal"],"private_input":"1 2 # 3","private_output":"2"},
  {"slug":"extra-tree-leaf-count","title":"Count Binary Tree Leaves","difficulty":"easy","topic":"trees-and-binary-search-trees","subtopic":"depth-first-traversals","description":"Count the leaf nodes of a binary tree encoded in level order with # for missing nodes.","input_format":"Space-separated level-order node values, with # for missing nodes.","output_format":"Print the number of leaves. An empty tree is encoded as # and has zero leaves.","constraints":["1 <= token count <= 200000","Node values are distinct integers."],"examples":[{"input":"8 4 12 2 6 # 14","output":"3"},{"input":"#","output":"0"}],"hints":[{"text":"A node is a leaf when both of its child positions are missing."}],"tags":["tree-traversal"],"private_input":"1 2 3 4 # # 5","private_output":"2"},
  {"slug":"extra-kth-largest-value","title":"K-th Largest Value","difficulty":"easy","topic":"heaps-and-priority-queues","subtopic":"top-k-problems","description":"Find the k-th largest value in a sequence, counting duplicate values separately.","input_format":"Integers n and k followed by n integers.","output_format":"Print the k-th largest value.","constraints":["1 <= k <= n <= 200000","-10^9 <= value <= 10^9"],"examples":[{"input":"6 3\n7 2 9 4 9 1","output":"7"},{"input":"4 1\n-8 -3 -5 -1","output":"-1"}],"hints":[{"text":"A size-k min-heap keeps the k largest values seen so far."}],"tags":["sorting"],"private_input":"5 5\n3 3 1 2 4","private_output":"1"},
  {"slug":"extra-graph-vertex-degrees","title":"Graph Vertex Degrees","difficulty":"easy","topic":"graphs","subtopic":"graph-representations","description":"Given an undirected graph, report the degree of every vertex. There are no self-loops or duplicate edges.","input_format":"Integers n and m followed by m pairs of zero-based vertex labels.","output_format":"Print n degrees in vertex order.","constraints":["1 <= n <= 200000","0 <= m <= min(200000, n*(n-1)/2)"],"examples":[{"input":"4 3\n0 1\n1 2\n1 3","output":"1 3 1 1"},{"input":"3 0","output":"0 0 0"}],"hints":[{"text":"Each undirected edge contributes one degree to each endpoint."}],"tags":["graph-traversal"],"private_input":"2 1\n0 1","private_output":"1 1"},
  {"slug":"extra-fibonacci-modulo","title":"Fibonacci Modulo","difficulty":"easy","topic":"dynamic-programming","subtopic":"one-dimensional-dp","description":"Compute the n-th Fibonacci number modulo 1000000007, with F(0)=0 and F(1)=1.","input_format":"One integer n.","output_format":"Print F(n) modulo 1000000007.","constraints":["0 <= n <= 1000000"],"examples":[{"input":"10","output":"55"},{"input":"0","output":"0"}],"hints":[{"text":"Keep only the previous two values to compute the sequence iteratively."}],"tags":["dynamic-programming"],"private_input":"50","private_output":"586268941"},
  {"slug":"extra-staircase-ways","title":"Ways Up the Staircase","difficulty":"easy","topic":"dynamic-programming","subtopic":"one-dimensional-dp","description":"Count the ways to climb n steps when each move climbs either one or two steps. The order of moves matters.","input_format":"One integer n.","output_format":"Print the number of ways modulo 1000000007.","constraints":["0 <= n <= 1000000"],"examples":[{"input":"4","output":"5"},{"input":"1","output":"1"}],"hints":[{"text":"Ways(n) equals Ways(n-1) plus Ways(n-2), with one way to stand at step zero."}],"tags":["dynamic-programming"],"private_input":"5","private_output":"8"},
  {"slug":"extra-trie-prefix-exists","title":"Dictionary Prefix Exists","difficulty":"easy","topic":"tries","subtopic":"prefix-search","description":"Given a dictionary of words and query prefixes, report whether any dictionary word starts with each prefix.","input_format":"Integers n and q, then n lowercase words followed by q lowercase prefixes.","output_format":"Print YES or NO for each prefix on its own line.","constraints":["1 <= n,q <= 100000","Each word and prefix has length 1 through 100."],"examples":[{"input":"3 3\napple apply berry\napp apz berry","output":"YES\nNO\nYES"},{"input":"1 2\ncat ca dog","output":"YES\nNO"}],"hints":[{"text":"A trie can answer each prefix query by following its characters from the root."}],"tags":["trie"],"private_input":"2 1\nab cd\na","private_output":"YES"},
  {"slug":"extra-power-of-two-check","title":"Power of Two Check","difficulty":"easy","topic":"bit-manipulation","subtopic":"bitwise-operators","description":"For each nonnegative integer, determine whether it is an exact power of two.","input_format":"An integer q followed by q nonnegative integers.","output_format":"Print YES or NO for each integer on its own line.","constraints":["1 <= q <= 100000","0 <= value <= 2^63-1"],"examples":[{"input":"4\n1 2 12 32","output":"YES\nYES\nNO\nYES"},{"input":"3\n3 4 0","output":"NO\nYES\nNO"}],"hints":[{"text":"A positive power of two has exactly one set bit in its binary representation."}],"tags":["bit-manipulation"],"private_input":"2\n8 16","private_output":"YES\nYES"},

  {"slug":"extra-product-except-self","title":"Product Except Self","difficulty":"medium","topic":"arrays","subtopic":"prefix-sum","description":"For every position, print the product of all other values without using division.","input_format":"An integer n followed by n integers.","output_format":"Print n products in original order.","constraints":["2 <= n <= 200000","-1000 <= value <= 1000","Every output fits in a signed 64-bit integer."],"examples":[{"input":"4\n1 2 3 4","output":"24 12 8 6"},{"input":"3\n-1 1 0","output":"0 0 -1"}],"hints":[{"text":"Combine a prefix product before each index with a suffix product after it."}],"tags":["prefix-sums"],"private_input":"3\n2 0 5","private_output":"0 10 0"},
  {"slug":"extra-longest-consecutive-run","title":"Longest Consecutive Run","difficulty":"medium","topic":"arrays","subtopic":"array-traversal","description":"Find the length of the longest set of consecutive integer values in an unsorted sequence. The values need not be adjacent in the input.","input_format":"An integer n followed by n integers.","output_format":"Print the longest consecutive run length.","constraints":["0 <= n <= 200000","-10^9 <= value <= 10^9"],"examples":[{"input":"6\n100 4 200 1 3 2","output":"4"},{"input":"5\n9 9 8 7 9","output":"3"}],"hints":[{"text":"Start a run only at a value whose predecessor is absent from the set."}],"tags":["hash-map"],"private_input":"4\n-2 0 -1 5","private_output":"3"},
  {"slug":"extra-range-sum-queries","title":"Static Range Sum Queries","difficulty":"medium","topic":"arrays","subtopic":"prefix-sum","description":"Answer inclusive range-sum queries on an array that never changes.","input_format":"Integers n and q, followed by n values and q pairs of zero-based inclusive indices l and r.","output_format":"Print each range sum on its own line.","constraints":["1 <= n,q <= 200000","0 <= l <= r < n","-10^9 <= value <= 10^9"],"examples":[{"input":"5 3\n2 -1 4 3 5\n0 2\n1 4\n3 3","output":"5\n11\n3"},{"input":"3 1\n0 0 0\n0 2","output":"0"}],"hints":[{"text":"A prefix-sum array makes each query a subtraction of two cumulative totals."}],"tags":["prefix-sums"],"private_input":"4 2\n1 2 3 4\n0 3\n2 3","private_output":"10\n7"},
  {"slug":"extra-minimum-window-distinct","title":"Minimum Window with All Categories","difficulty":"medium","topic":"arrays","subtopic":"sliding-window","description":"Find the shortest contiguous range containing every distinct category present in the full sequence.","input_format":"An integer n followed by n category identifiers.","output_format":"Print the minimum range length.","constraints":["1 <= n <= 200000","0 <= category <= 10^9"],"examples":[{"input":"7\n1 2 1 3 2 2 1","output":"3"},{"input":"4\n5 5 5 5","output":"1"}],"hints":[{"text":"Use a frequency map while expanding and shrinking a window."}],"tags":["sliding-window"],"private_input":"5\n1 2 3 1 2","private_output":"3"},
  {"slug":"extra-longest-distinct-substring","title":"Longest Distinct-Character Substring","difficulty":"medium","topic":"strings","subtopic":"string-fundamentals","description":"Find the length of the longest substring with no repeated characters.","input_format":"A non-empty string of lowercase English letters.","output_format":"Print the maximum substring length.","constraints":["1 <= string length <= 200000"],"examples":[{"input":"abcabcbb","output":"3"},{"input":"bbbbb","output":"1"}],"hints":[{"text":"When a repeated character enters the window, move its left edge past the previous occurrence."}],"tags":["sliding-window","strings"],"private_input":"pwwkew","private_output":"3"},
  {"slug":"extra-minimum-anagram-deletions","title":"Minimum Deletions for Anagrams","difficulty":"medium","topic":"strings","subtopic":"character-frequency","description":"Find the minimum total number of character deletions needed to make two lowercase strings anagrams.","input_format":"Two lowercase strings on separate lines.","output_format":"Print the minimum number of deletions.","constraints":["1 <= length of each string <= 200000"],"examples":[{"input":"cde\nabc","output":"4"},{"input":"listen\nsilent","output":"0"}],"hints":[{"text":"For each letter, delete the difference between its two frequencies."}],"tags":["strings","hash-map"],"private_input":"aabb\nabcc","private_output":"4"},
  {"slug":"extra-group-anagrams","title":"Group Anagrams","difficulty":"medium","topic":"hashing","subtopic":"grouping-and-anagrams","description":"Group lowercase words that are anagrams. Sort words within each group and order groups by their first word.","input_format":"An integer n followed by n lowercase words.","output_format":"Print each group on its own line, with words separated by spaces.","constraints":["1 <= n <= 10000","1 <= word length <= 100"],"examples":[{"input":"6\neat tea tan ate nat bat","output":"ate eat tea\nbat\nnat tan"},{"input":"3\nabc bca cab","output":"abc bca cab"}],"hints":[{"text":"Use the sorted characters of each word as its group key."}],"tags":["hash-map","strings"],"private_input":"4\nab ba xy yx","private_output":"ab ba\nxy yx"},
  {"slug":"extra-longest-zero-sum-subarray","title":"Longest Zero-Sum Subarray","difficulty":"medium","topic":"hashing","subtopic":"frequency-counting","description":"Find the length of the longest contiguous subarray whose sum is zero.","input_format":"An integer n followed by n integers.","output_format":"Print the longest zero-sum subarray length.","constraints":["0 <= n <= 200000","-10^9 <= value <= 10^9"],"examples":[{"input":"5\n1 2 -3 3 -3","output":"5"},{"input":"4\n1 2 3 4","output":"0"}],"hints":[{"text":"If the same prefix sum occurs twice, the values between those positions sum to zero."}],"tags":["prefix-sums","hash-map"],"private_input":"5\n0 0 1 -1 2","private_output":"4"},
  {"slug":"extra-three-sum-zero","title":"Three Values Sum to Zero","difficulty":"medium","topic":"two-pointers-and-sliding-window","subtopic":"opposite-direction-pointers","description":"Return the number of distinct value triplets whose sum is zero. A triplet is distinct by its sorted values, not by indices.","input_format":"An integer n followed by n integers.","output_format":"Print the number of distinct zero-sum triplets.","constraints":["0 <= n <= 4000","-10^9 <= value <= 10^9"],"examples":[{"input":"6\n-1 0 1 2 -1 -4","output":"2"},{"input":"3\n0 0 0","output":"1"}],"hints":[{"text":"Sort the values, fix one value, then use two pointers and skip duplicates."}],"tags":["two-pointers","sorting"],"private_input":"4\n-2 0 1 1","private_output":"1"},
  {"slug":"extra-container-maximum-area","title":"Maximum Container Area","difficulty":"medium","topic":"two-pointers-and-sliding-window","subtopic":"opposite-direction-pointers","description":"Given nonnegative heights, choose two positions that form a container with the greatest area. The area is width times the shorter height.","input_format":"An integer n followed by n nonnegative heights.","output_format":"Print the maximum container area.","constraints":["2 <= n <= 200000","0 <= height <= 10^9"],"examples":[{"input":"9\n1 8 6 2 5 4 8 3 7","output":"49"},{"input":"3\n1 1 1","output":"2"}],"hints":[{"text":"After measuring an endpoint pair, move the endpoint with the shorter height."}],"tags":["two-pointers"],"private_input":"4\n0 5 0 5","private_output":"10"},
  {"slug":"extra-rotated-array-search","title":"Search a Rotated Sorted Array","difficulty":"medium","topic":"searching-and-sorting","subtopic":"binary-search-fundamentals","description":"Search for a target in a strictly increasing array that was rotated at an unknown pivot.","input_format":"Integers n and target followed by n rotated sorted values.","output_format":"Print the target index, or -1 if it is absent.","constraints":["0 <= n <= 200000","Values are distinct integers in [-10^9,10^9]."],"examples":[{"input":"7 0\n4 5 6 7 0 1 2","output":"4"},{"input":"5 3\n6 7 1 2 4","output":"-1"}],"hints":[{"text":"At least one half around the midpoint remains sorted."}],"tags":["binary-search"],"private_input":"4 6\n5 6 1 2","private_output":"1"},
  {"slug":"extra-integer-square-root","title":"Integer Square Root","difficulty":"easy","topic":"searching-and-sorting","subtopic":"binary-search-fundamentals","description":"For a nonnegative integer x, return the greatest integer r for which r squared is at most x.","input_format":"One nonnegative integer x.","output_format":"Print floor(sqrt(x)).","constraints":["0 <= x <= 10^18"],"examples":[{"input":"26","output":"5"},{"input":"49","output":"7"}],"hints":[{"text":"Binary-search the largest feasible candidate and avoid overflowing when squaring."}],"tags":["binary-search"],"private_input":"0","private_output":"0"},
  {"slug":"extra-merge-overlapping-intervals","title":"Merge Overlapping Intervals","difficulty":"medium","topic":"searching-and-sorting","subtopic":"merge-sort","description":"Merge all closed intervals that overlap or touch at an endpoint, then print the merged intervals in increasing order.","input_format":"An integer n followed by n pairs of interval endpoints l and r.","output_format":"Print one merged interval per line.","constraints":["0 <= n <= 200000","-10^9 <= l <= r <= 10^9"],"examples":[{"input":"4\n1 3\n2 6\n8 10\n10 12","output":"1 6\n8 12"},{"input":"3\n1 2\n2 3\n3 4","output":"1 4"}],"hints":[{"text":"Sort by start point, then extend the current interval whenever the next one touches it."}],"tags":["sorting"],"private_input":"2\n-3 0\n0 2","private_output":"-3 2"},
  {"slug":"extra-merge-sorted-lists","title":"Merge Two Sorted Lists","difficulty":"medium","topic":"linked-lists","subtopic":"insertion-and-deletion","description":"Merge two nondecreasing integer lists into one nondecreasing list while preserving every value.","input_format":"Integers n and m, followed by n sorted values and then m sorted values.","output_format":"Print the merged values on one line, or NONE if both lists are empty.","constraints":["0 <= n,m <= 200000","-10^9 <= value <= 10^9"],"examples":[{"input":"4 3\n1 3 3 8\n2 3 9","output":"1 2 3 3 3 8 9"},{"input":"0 2\n-1 4","output":"-1 4"}],"hints":[{"text":"Advance the pointer holding the smaller current value."}],"tags":["linked-list","two-pointers"],"private_input":"2 2\n0 5\n1 4","private_output":"0 1 4 5"},
  {"slug":"extra-swap-adjacent-list-pairs","title":"Swap Adjacent List Pairs","difficulty":"medium","topic":"linked-lists","subtopic":"reversing-a-list","description":"Swap every adjacent pair of values in a list. If the list has odd length, keep its final value in place.","input_format":"An integer n followed by n list values.","output_format":"Print the transformed list on one line, or NONE if it is empty.","constraints":["0 <= n <= 200000","-10^9 <= value <= 10^9"],"examples":[{"input":"5\n1 2 3 4 5","output":"2 1 4 3 5"},{"input":"2\n8 9","output":"9 8"}],"hints":[{"text":"Process two nodes at a time and reconnect the preceding part to the swapped pair."}],"tags":["linked-list"],"private_input":"1\n7","private_output":"7"},
  {"slug":"extra-daily-warmer-days","title":"Days Until a Warmer Day","difficulty":"medium","topic":"stacks-and-queues","subtopic":"monotonic-stacks","description":"For each daily temperature, find how many days must pass until a warmer temperature. Use zero if none occurs later.","input_format":"An integer n followed by n temperatures.","output_format":"Print one wait length per day.","constraints":["0 <= n <= 200000","-100 <= temperature <= 100"],"examples":[{"input":"8\n73 74 75 71 69 72 76 73","output":"1 1 4 2 1 1 0 0"},{"input":"4\n30 20 10 0","output":"0 0 0 0"}],"hints":[{"text":"A decreasing stack of unresolved days can be completed when a warmer value arrives."}],"tags":["stack"],"private_input":"3\n1 2 3","private_output":"1 1 0"},
  {"slug":"extra-rpn-expression","title":"Evaluate a Postfix Expression","difficulty":"medium","topic":"stacks-and-queues","subtopic":"expression-parsing","description":"Evaluate a valid reverse Polish notation expression using integer arithmetic. Division truncates toward zero.","input_format":"A space-separated postfix expression using integers and the operators +, -, *, and /.","output_format":"Print the expression result.","constraints":["1 <= token count <= 100000","Every intermediate result fits in a signed 64-bit integer.","The expression is valid and division by zero does not occur."],"examples":[{"input":"2 1 + 3 *","output":"9"},{"input":"4 13 5 / +","output":"6"}],"hints":[{"text":"Push operands; when an operator appears, pop the right operand before the left one."}],"tags":["stack"],"private_input":"7 2 - 3 *","private_output":"15"},
  {"slug":"extra-generate-parentheses","title":"Generate Balanced Parentheses","difficulty":"medium","topic":"recursion-and-backtracking","subtopic":"constraint-search","description":"Generate every balanced string containing n pairs of parentheses in lexicographic order.","input_format":"One integer n.","output_format":"Print each valid string on its own line. Print an empty line when n is zero.","constraints":["0 <= n <= 10"],"examples":[{"input":"2","output":"(())\n()()"},{"input":"1","output":"()"}],"hints":[{"text":"Add an opening parenthesis while fewer than n have been used; close only an unmatched opening one."}],"tags":["backtracking"],"private_input":"3","private_output":"((()))\n(()())\n(())()\n()(())\n()()()"},
