  {"slug":"extra-maximum-submatrix-sum","title":"Maximum Submatrix Sum","difficulty":"hard","topic":"arrays","subtopic":"matrix-problems","description":"Find the maximum sum of any non-empty axis-aligned rectangular region of an integer grid.","input_format":"Integers r and c followed by r rows of c integers.","output_format":"Print the maximum rectangular-region sum.","constraints":["1 <= r,c <= 200","-10^6 <= cell <= 10^6"],"examples":[{"input":"3 4\n1 -2 -1 4\n-8 3 4 2\n3 8 10 -8","output":"25"},{"input":"2 2\n-5 -2\n-3 -4","output":"-2"}],"hints":[{"text":"Fix two row boundaries, compress the columns between them, then run a maximum-subarray scan."}],"tags":["dynamic-programming","array-scan"],"private_input":"1 3\n-1 4 -2","private_output":"4"},
  {"slug":"extra-edit-distance","title":"Edit Distance","difficulty":"hard","topic":"strings","subtopic":"string-fundamentals","description":"Find the minimum number of single-character insertions, deletions, and substitutions needed to transform one string into another.","input_format":"Two lowercase strings on separate lines.","output_format":"Print the minimum edit distance.","constraints":["1 <= length of each string <= 2000"],"examples":[{"input":"kitten\nsitting","output":"3"},{"input":"flaw\nlawn","output":"2"}],"hints":[{"text":"The final characters either match or require one edit after a smaller prefix problem."}],"tags":["dynamic-programming","strings"],"private_input":"a\nb","private_output":"1"},
  {"slug":"extra-distinct-subarray-count","title":"Count Distinct Subarrays","difficulty":"hard","topic":"hashing","subtopic":"hash-collisions","description":"Count distinct non-empty contiguous subarrays. Two subarrays are equal when their entire value sequences match.","input_format":"An integer n followed by n integers.","output_format":"Print the number of distinct non-empty subarrays.","constraints":["0 <= n <= 5000","-10^9 <= value <= 10^9"],"examples":[{"input":"3\n1 2 1","output":"5"},{"input":"3\n7 7 7","output":"3"}],"hints":[{"text":"A trie of sequences or collision-checked rolling hashes can share common prefixes."}],"tags":["hash-map","strings"],"private_input":"2\n1 2","private_output":"3"},
  {"slug":"extra-trapping-rain-water","title":"Trapping Rain Water","difficulty":"hard","topic":"two-pointers-and-sliding-window","subtopic":"window-invariants","description":"Given nonnegative bar heights of unit width, compute how many units of water remain after raining.","input_format":"An integer n followed by n nonnegative heights.","output_format":"Print the total trapped water.","constraints":["0 <= n <= 200000","0 <= height <= 10^9"],"examples":[{"input":"12\n0 1 0 2 1 0 1 3 2 1 2 1","output":"6"},{"input":"6\n4 2 0 3 2 5","output":"9"}],"hints":[{"text":"Water above a position is limited by the shorter of the highest bars on its two sides."}],"tags":["two-pointers"],"private_input":"3\n2 0 2","private_output":"2"},
  {"slug":"extra-list-cycle-entry","title":"Find the Entry of a Linked-List Cycle","difficulty":"hard","topic":"linked-lists","subtopic":"cycle-detection","description":"A list follows next pointers through n nodes; the final node points to index c, or -1 for no cycle. Find the first index in the cycle, or -1.","input_format":"Integers n and c, where node indices are 0 through n-1.","output_format":"Print the cycle-entry index or -1.","constraints":["0 <= n <= 200000","-1 <= c < n"],"examples":[{"input":"6 2","output":"2"},{"input":"4 -1","output":"-1"}],"hints":[{"text":"Floyd slow and fast pointers detect a cycle; reset one pointer to the head to find its entry."}],"tags":["linked-list"],"private_input":"1 0","private_output":"0"},
  {"slug":"extra-largest-histogram-rectangle","title":"Largest Rectangle in a Histogram","difficulty":"hard","topic":"stacks-and-queues","subtopic":"monotonic-stacks","description":"Find the largest rectangular area that can be formed from consecutive histogram bars.","input_format":"An integer n followed by n nonnegative bar heights.","output_format":"Print the maximum rectangle area.","constraints":["0 <= n <= 200000","0 <= height <= 10^9"],"examples":[{"input":"6\n2 1 5 6 2 3","output":"10"},{"input":"5\n2 4 4 4 2","output":"12"}],"hints":[{"text":"When a shorter bar arrives, it determines the right boundary for taller bars on a monotonic stack."}],"tags":["stack"],"private_input":"4\n1 2 3 4","private_output":"6"},
  {"slug":"extra-binary-tree-diameter","title":"Binary Tree Diameter","difficulty":"hard","topic":"trees-and-binary-search-trees","subtopic":"tree-recursion-patterns","description":"Find the greatest number of edges on a path between any two nodes in a binary tree encoded in level order with # for missing nodes.","input_format":"Space-separated level-order values, using # for missing nodes.","output_format":"Print the tree diameter in edges; an empty or single-node tree has diameter 0.","constraints":["1 <= token count <= 200000","Node values are distinct integers."],"examples":[{"input":"1 2 3 4 5","output":"3"},{"input":"1","output":"0"}],"hints":[{"text":"For each node, combine the heights of its left and right subtrees."}],"tags":["tree-traversal"],"private_input":"1 2 # 3 # 4","private_output":"3"},
  {"slug":"extra-dijkstra-shortest-path","title":"Weighted Shortest Path","difficulty":"hard","topic":"graphs","subtopic":"shortest-paths","description":"Find the minimum total weight from a source to every vertex in a directed graph with nonnegative edge weights.","input_format":"Integers n, m, source followed by m directed edges u, v, weight.","output_format":"Print one distance per vertex in index order, using -1 when unreachable.","constraints":["1 <= n <= 200000","0 <= m <= 300000","0 <= weight <= 10^9"],"examples":[{"input":"5 6 0\n0 1 4\n0 2 1\n2 1 2\n1 3 1\n2 3 5\n3 4 3","output":"0 3 1 4 7"},{"input":"3 1 1\n1 2 8","output":"-1 0 8"}],"hints":[{"text":"Use a min-priority queue and discard stale distances when they are popped."}],"tags":["graph-traversal","sorting"],"private_input":"2 1 0\n0 1 0","private_output":"0 0"},
  {"slug":"extra-weighted-interval-scheduling","title":"Weighted Interval Scheduling","difficulty":"hard","topic":"dynamic-programming","subtopic":"state-and-recurrence-design","description":"Choose non-overlapping half-open jobs to maximize total profit. A job ending at t may be followed by one starting at t.","input_format":"An integer n followed by n triples start, end, profit.","output_format":"Print the maximum achievable profit.","constraints":["0 <= n <= 200000","0 <= start < end <= 10^9","0 <= profit <= 10^9"],"examples":[{"input":"4\n1 3 5\n2 5 6\n4 6 5\n6 7 4","output":"14"},{"input":"3\n1 2 3\n2 3 4\n3 4 5","output":"12"}],"hints":[{"text":"Sort jobs by end time and binary-search the best compatible earlier job."}],"tags":["dynamic-programming","binary-search"],"private_input":"2\n0 2 4\n2 3 5","private_output":"9"},
  {"slug":"extra-target-sum-assignments","title":"Target Sum Assignments","difficulty":"hard","topic":"dynamic-programming","subtopic":"knapsack-patterns","description":"Place either a plus or minus sign before each value and count the assignments whose signed sum equals the target.","input_format":"Integers n and target followed by n nonnegative values.","output_format":"Print the number of assignments.","constraints":["0 <= n <= 40","0 <= value <= 10^9","-10^9 <= target <= 10^9"],"examples":[{"input":"5 3\n1 1 1 1 1","output":"5"},{"input":"3 1\n0 0 1","output":"4"}],"hints":[{"text":"The count can be expressed using subset sums, or by combining sums from two halves."}],"tags":["dynamic-programming","backtracking"],"private_input":"1 0\n0","private_output":"2"}
]
$problems$::JSONB) AS value
  LOOP
    IF problem_data->>'difficulty' = 'easy' THEN
      seeded_easy := seeded_easy + 1;
    ELSIF problem_data->>'difficulty' = 'medium' THEN
      seeded_medium := seeded_medium + 1;
    ELSIF problem_data->>'difficulty' = 'hard' THEN
      seeded_hard := seeded_hard + 1;
    ELSE
      RAISE EXCEPTION 'Invalid difficulty in problem seed: %', problem_data->>'slug';
    END IF;

    SELECT topics.id INTO topic_id
    FROM public.topics
    WHERE topics.slug = problem_data->>'topic'
      AND topics.is_published;
    IF topic_id IS NULL THEN
      RAISE EXCEPTION 'Published topic not found for problem %', problem_data->>'slug';
    END IF;

    SELECT subtopics.id INTO subtopic_id
    FROM public.subtopics
    WHERE subtopics.topic_id = topic_id
      AND subtopics.slug = problem_data->>'subtopic'
      AND subtopics.is_published;
    IF subtopic_id IS NULL THEN
      RAISE EXCEPTION 'Published subtopic not found for problem %', problem_data->>'slug';
    END IF;

    INSERT INTO public.problems (
      title, slug, description, difficulty, topic_id, subtopic_id,
      constraints, input_format, output_format, examples, hints,
      supported_languages, starter_code, is_published
    )
    VALUES (
      problem_data->>'title',
      problem_data->>'slug',
      problem_data->>'description',
      problem_data->>'difficulty',
      topic_id,
      subtopic_id,
      ARRAY(SELECT jsonb_array_elements_text(problem_data->'constraints')),
      problem_data->>'input_format',
      problem_data->>'output_format',
      problem_data->'examples',
      problem_data->'hints',
      ARRAY['cpp', 'python'],
      jsonb_build_object('cpp', cpp_starter, 'python', python_starter),
      TRUE
    )
    ON CONFLICT (slug) DO UPDATE SET
      title = EXCLUDED.title,
      description = EXCLUDED.description,
      difficulty = EXCLUDED.difficulty,
      topic_id = EXCLUDED.topic_id,
      subtopic_id = EXCLUDED.subtopic_id,
      constraints = EXCLUDED.constraints,
      input_format = EXCLUDED.input_format,
      output_format = EXCLUDED.output_format,
      examples = EXCLUDED.examples,
      hints = EXCLUDED.hints,
      supported_languages = EXCLUDED.supported_languages,
      starter_code = EXCLUDED.starter_code,
      is_published = TRUE
    RETURNING id INTO problem_id;

    example_index := 0;
    FOR example_data IN
      SELECT value FROM jsonb_array_elements(problem_data->'examples')
    LOOP
      INSERT INTO public.problem_test_cases (
        problem_id, input, expected_output, is_sample, sort_order
      )
      VALUES (
        problem_id,
        example_data->>'input',
        example_data->>'output',
        TRUE,
        example_index
      )
      ON CONFLICT (problem_id, sort_order) DO UPDATE SET
        input = EXCLUDED.input,
        expected_output = EXCLUDED.expected_output,
        is_sample = TRUE;
      example_index := example_index + 1;
    END LOOP;

    INSERT INTO public.problem_test_cases (
      problem_id, input, expected_output, is_sample, sort_order
    )
    VALUES (
      problem_id,
      problem_data->>'private_input',
      problem_data->>'private_output',
      FALSE,
      10
    )
    ON CONFLICT (problem_id, sort_order) DO UPDATE SET
      input = EXCLUDED.input,
      expected_output = EXCLUDED.expected_output,
      is_sample = FALSE;
    private_test_count := private_test_count + 1;

    FOR tag_slug IN
      SELECT jsonb_array_elements_text(problem_data->'tags')
    LOOP
      INSERT INTO public.problem_tags (name, slug)
      VALUES (initcap(replace(tag_slug, '-', ' ')), tag_slug)
      ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name
      RETURNING id INTO tag_id;

      INSERT INTO public.problem_tag_relations (problem_id, tag_id)
      VALUES (problem_id, tag_id)
      ON CONFLICT (problem_id, tag_id) DO NOTHING;
    END LOOP;
  END LOOP;

  IF seeded_easy <> 30 OR seeded_medium <> 30 OR seeded_hard <> 10
     OR private_test_count <> 70 THEN
    RAISE EXCEPTION
      'Expected 70 problems (30 easy, 30 medium, 10 hard) with private tests; got % easy, % medium, % hard, % private tests',
      seeded_easy, seeded_medium, seeded_hard, private_test_count;
  END IF;

  SELECT
    count(*) FILTER (WHERE difficulty = 'easy'),
    count(*) FILTER (WHERE difficulty = 'medium'),
    count(*) FILTER (WHERE difficulty = 'hard'),
    count(*)
  INTO published_easy, published_medium, published_hard, published_total
  FROM public.problems
  WHERE is_published;

  IF published_total <> 100 OR published_easy <> 40
     OR published_medium <> 40 OR published_hard <> 20 THEN
    RAISE EXCEPTION
      'Published problem bank must contain exactly 100 problems (40 easy, 40 medium, 20 hard); got % total (% easy, % medium, % hard)',
      published_total, published_easy, published_medium, published_hard;
  END IF;
END;
$seed$;
